//! 🧪️ Typed root publication preserves exact original pointers through all independent grant denials.
use super::*;
use std::sync::atomic::{AtomicUsize,Ordering};
struct Decision(AtomicUsize);
impl crate::FactoryPayloadRetirement for Decision{type CloseState=();fn close_state_birth_bytes(&self)->usize{0}fn close_state_constructor_depth(&self)->usize{0}fn close_state_constructor_copy_bytes(&self)->usize{0}fn prepare_close_state(&self){}fn close_state_preparation_demands(&self,_:&(),_:usize)->Result<RetirementDemand,ValueError>{Ok(Default::default())}fn prepare_close_state_step(&self,_:&mut(),_:RetainedCloneGrant)->Result<crate::RetainedCloneStep,ValueError>{Ok(crate::RetainedCloneStep::Complete(Default::default()))}fn close_state_preparation_is_complete(_:&())->bool{true}fn transfer_payload(_value:Self,_:&mut()){}fn close_state_demands(_:&(),_:usize)->Result<RetirementDemand,ValueError>{Ok(Default::default())}fn close_state_step(_:&mut(),_:RetainedCloneGrant)->Result<crate::RetainedCloneStep,ValueError>{Ok(crate::RetainedCloneStep::Complete(Default::default()))}fn close_state_terminal_is_empty(_:&())->bool{true}}
impl RetainedPublicationDecision for Decision{fn committed(&self)->bool{self.0.load(Ordering::Acquire)==1}fn pending(&self)->bool{self.0.load(Ordering::Acquire)==0}fn into_retirement(self:Arc<Self>)->FactoryAuthority{FactoryAuthority::new(self)}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn deny(mut g:RetainedCloneGrant,axis:&str)->RetainedCloneGrant{match axis{"items"=>g.maximum_items=0,"copy"=>g.maximum_copy_bytes=0,"capacity"=>g.maximum_capacity_bytes=0,"release"=>g.maximum_release_bytes=0,"depth"=>g.maximum_depth=0,_=>panic!()}g}
#[test]
fn original_publication_root_reveals_all_candidates_at_one_decision_and_returns_original_owners(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for decision in law["decisions"].as_array().unwrap(){let gate=Arc::new(Decision(AtomicUsize::new(0)));let mut root=RetainedPublicationRoot::new(vec![3u64,5]);let pointer=root.as_ptr();let mut candidate=Some(vec![7u64,11]);let next_pointer=candidate.as_ref().unwrap().as_ptr();let mut view:Option<Arc<dyn RetainedPublicationDecision>>=Some(gate.clone());let d=RetainedPublicationRoot::<Vec<u64>>::stage_demands();for axis in law["deniedAxes"].as_array().unwrap(){let(p,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||root.stage(&mut candidate,&mut view,deny(grant(d),axis.as_str().unwrap())).unwrap());assert_eq!(p,Default::default());assert_eq!(heap,(0,0));assert_eq!(candidate.as_ref().unwrap().as_ptr(),next_pointer);assert_eq!(root.as_ptr(),pointer);}let(p,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||root.stage(&mut candidate,&mut view,grant(d)).unwrap());assert_eq!(heap,(p.retained_capacity_bytes,0));assert!(candidate.is_none()&&view.is_none());let(mut displaced,mut retirement)=(None,None);assert_eq!(root.settle(&mut displaced,&mut retirement,grant(root.settlement_demands())).unwrap(),Default::default());assert_eq!(root.as_ptr(),pointer);gate.0.store(if decision=="commit"{1}else{2},Ordering::Release);assert_eq!(root.as_slice(),if decision=="commit"{&[7,11]}else{&[3,5]});let d=root.settlement_demands();for axis in law["deniedSettlementAxes"].as_array().unwrap(){let(p,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||root.settle(&mut displaced,&mut retirement,deny(grant(d),axis.as_str().unwrap())).unwrap());assert_eq!(p,Default::default());assert_eq!(heap,(0,0));assert!(displaced.is_none()&&retirement.is_none());}let(p,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||root.settle(&mut displaced,&mut retirement,grant(d)).unwrap());assert_eq!(heap,(0,p.released_bytes));assert_eq!(displaced.as_ref().unwrap().as_ptr(),if decision=="commit"{pointer}else{next_pointer});assert_eq!(root.as_ptr(),if decision=="commit"{next_pointer}else{pointer});let mut retirement=retirement.unwrap();while !retirement.terminal_is_empty(){let d=retirement.demands(4096).unwrap();let(p,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||retirement.step(grant(d)).unwrap().progress());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));}drop(retirement);drop(root.into_original().ok().unwrap());drop(displaced);drop(gate);}
}

#[test]
fn original_publication_roots_close_both_sources_before_and_after_shared_visibility(){
 use crate::retirement::controlled::ControlledRetirement;
 for state in [0,1,2]{let gate=Arc::new(Decision(AtomicUsize::new(0)));let mut first=RetainedPublicationRoot::new(vec![3u64,5]);let mut second=RetainedPublicationRoot::new(vec![13u64,17]);for(root,value)in [(&mut first,7),(&mut second,19)]{let mut candidate=Some(vec![value,value+4]);let mut decision:Option<Arc<dyn RetainedPublicationDecision>>=Some(gate.clone());let d=RetainedPublicationRoot::<Vec<u64>>::stage_demands();root.stage(&mut candidate,&mut decision,grant(d)).unwrap();}assert_eq!(first[0],3);assert_eq!(second[0],13);gate.0.store(state,Ordering::Release);assert_eq!((first[0],second[0]),if state==1{(7,19)}else{(3,13)});for root in [first,second]{let mut close=ControlledRetirement::new(root).ok().unwrap();for turn in 0..10000{if close.terminal_is_empty(){break}let d=close.next_demand(4096).unwrap();for axis in ["items","copy","capacity","release","depth"]{let value=match axis{"items"=>1,"copy"=>d.copy_bytes,"capacity"=>d.capacity_bytes,"release"=>d.release_bytes,_=>d.depth};if value==0{continue}let attempt=deny(grant(d),axis);let(before,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||close.step(attempt));assert_eq!(heap,(0,0));match before{Ok(step)=>assert_eq!(step.progress(),Default::default()),Err(error)=>assert_eq!(error.retained_progress(),Default::default())}}let(p,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||close.step(grant(d)).unwrap().progress());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(turn<9999);}assert!(close.terminal_is_empty());drop(close);}drop(gate);}
}
